// FV-P4C-2A — the durable status history under the real chain: FV-P2 eligibility, FV-P3 policy and the FV-P4C
// freshness gate of @aoc-enterprise/sovereign-receiver-verification, with the SQLite store closed and reopened between
// steps. Synthetic fixture only (tests/fixtures/fv-p4c2a-sqlite-status-history/chain.json, generated by
// packages/sovereign-receiver-verification/scripts/generate-document-freshness-fixture.mjs); no private key exists in it.
import { createRequire } from 'node:module';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

import {
  DOCUMENT_USE_FRESHNESS_CEILINGS,
  checkDocumentUseFreshness,
  createInMemoryStatusHighWaterMarkStore,
  establishStatusHistory,
  evaluateDocumentUsePolicy,
  verifyDocumentUseEligibility,
} from '@aoc-enterprise/sovereign-receiver-verification';

import { openSqliteStatusHighWaterMarkStore } from '../dist/src/enterprise/sovereign-status-history/index.js';
import { trustedBootstrap } from './fv-status-bootstrap-support.mjs';

const require = createRequire(import.meta.url);

const FIXTURE = JSON.parse(readFileSync(new URL('./fixtures/fv-p4c2a-sqlite-status-history/chain.json', import.meta.url), 'utf8'));
const READ = 'aoc.licensing:access';
const NAMESPACE = 'receiver:fv-p4c2a-e2e';
const S = FIXTURE.statuses;
const resolver = {
  resolveVerificationKey: (issuer) => (issuer === FIXTURE.registrant.issuer ? { keyId: FIXTURE.registrant.keyId, issuer, algorithm: 'ed25519' } : undefined),
};

async function eligible() {
  const result = await verifyDocumentUseEligibility(FIXTURE.bundleText, {
    verificationKeyResolver: resolver,
    expectedSovereignAssetId: FIXTURE.sovereignAssetId,
    contentBytes: new Uint8Array(Buffer.from(FIXTURE.contentBase64, 'base64')),
  });
  assert.equal(result.outcome, 'eligible_for_evaluation');
  return result;
}

function decide(eligibility, evaluationTime, action = READ) {
  return evaluateDocumentUsePolicy(eligibility, { action }, {
    receiverPrincipal: FIXTURE.receiver,
    evaluationTime,
    expectedSovereignAssetId: FIXTURE.sovereignAssetId,
    policyReference: { ...FIXTURE.terms },
  });
}

async function check(eligibility, store, status, evaluationTime) {
  const result = await checkDocumentUseFreshness(decide(eligibility, evaluationTime), status.text, {
    verificationKeyResolver: resolver,
    evaluationTime,
    operationId: `op-${evaluationTime}`,
    maxStatusAgeSeconds: { ...DOCUMENT_USE_FRESHNESS_CEILINGS },
    historyStore: store,
  });
  assert.equal(result.authorization, 'not_evaluated');
  assert.equal(result.execution, 'not_performed');
  assert.equal('decision' in result, false, 'never an RSDK-02B verdict');
  return result;
}

/**
 * Anchors a history and returns the receiver's reason. The in-memory reference store is anchored directly with
 * `establishStatusHistory`; the SQLite store (schema v2) accepts a history only with bootstrap evidence, so it is
 * anchored through the FV-P4C-2B1 coordinator with synthetic authority and source providers.
 */
async function bootstrap(store, status, evaluationTime, extra = {}) {
  if (typeof store.compareAndSetWithEvidence !== 'function') {
    const result = await establishStatusHistory(status.text, {
      verificationKeyResolver: resolver,
      historyStore: store,
      expectedSovereignAssetId: FIXTURE.sovereignAssetId,
      expectedRegistrant: FIXTURE.registrant.issuer,
      expectedManifestDigest: FIXTURE.manifestDigest,
      evaluationTime,
      ...extra,
    });
    return result.reason;
  }
  const result = await trustedBootstrap(store, status, evaluationTime, { operation: extra.reanchor ? 'reanchor' : 'establish' });
  return result.reason === 'HISTORY_REFUSED' ? result.detail : result.reason;
}

async function withDatabase(work) {
  const dir = mkdtempSync(join(tmpdir(), 'fv-p4c2a-e2e-'));
  try {
    return await work(join(dir, 'history.sqlite'));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const reopen = (path) => openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE });

describe('FV-P4C-2A — durable history through the real freshness gate', () => {
  it('the full chain survives restarts: fresh, withdrawn, replay, clock rollback, conflict, and no re-anchor clears it', async () => {
    await withDatabase(async (path) => {
      // 1–3. A verified, eligible document; READ is ALLOWED by policy.
      let eligibility = await eligible();
      assert.equal(decide(eligibility, '2026-10-28T12:00:00Z').decision, 'ALLOWED');

      // An initialized database is not a trusted history.
      let store = await openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE, create: true });
      assert.equal((await check(eligibility, store, S.active1, '2026-10-28T12:00:00Z')).freshnessVerdict, 'HISTORY_UNINITIALIZED');

      // 4–7. Trusted bootstrap at sequence 1, then FRESH.
      assert.equal((await bootstrap(store, S.active1, '2026-10-28T12:00:00Z')), 'ESTABLISHED');
      const fresh = await check(eligibility, store, S.active1, '2026-10-28T12:00:00Z');
      assert.equal(fresh.freshnessVerdict, 'FRESH');
      assert.equal(fresh.policyDecisionAfterFreshness, 'ALLOWED');

      // 8–10. Restart; the withdrawal at sequence 2 is accepted and denies.
      store.close();
      store = await reopen(path);
      const withdrawn = await check(eligibility, store, S.withdrawn2, '2026-10-28T12:01:00Z');
      assert.equal(withdrawn.freshnessVerdict, 'WITHDRAWN');
      assert.equal(withdrawn.policyDecisionAfterFreshness, 'DENIED');
      assert.equal(withdrawn.history.transition, 'advanced');

      // 11–13. Restart again (a fresh process would also re-verify eligibility); replaying sequence 1 is a rollback.
      store.close();
      store = await reopen(path);
      eligibility = await eligible();
      const replay = await check(eligibility, store, S.active1, '2026-10-28T12:02:00Z');
      assert.equal(replay.freshnessVerdict, 'ROLLBACK_DETECTED');
      assert.equal(replay.policyDecisionAfterFreshness, 'DENIED');
      // The time floor survived the restart: a trusted clock behind the accepted withdrawal is a rollback.
      assert.equal((await check(eligibility, store, S.active1, '2026-10-28T11:54:00Z')).freshnessVerdict, 'CLOCK_ROLLBACK_DETECTED');

      // 14–15. A re-anchor cannot reopen the withdrawal.
      assert.equal((await bootstrap(store, S.reopening3, '2026-10-28T12:03:00Z', { reanchor: true })), 'REANCHOR_REACTIVATES_WITHDRAWN');
      assert.equal((await check(eligibility, store, S.reopening3, '2026-10-28T12:03:00Z')).freshnessVerdict, 'CONFLICT_DETECTED');

      // The conflict latch survives restarts, new instances and every re-anchor attempt.
      store.close();
      store = await reopen(path);
      const second = await reopen(path);
      for (const candidate of [S.withdrawn2, S.reopening3, S.equivocating2]) {
        assert.equal((await bootstrap(store, candidate, '2026-10-28T12:04:00Z', { reanchor: true })), 'CONFLICT_DETECTED');
        assert.equal((await bootstrap(second, candidate, '2026-10-28T12:04:00Z')), 'CONFLICT_DETECTED');
        assert.equal((await check(eligibility, second, candidate, '2026-10-28T12:04:00Z')).freshnessVerdict, 'CONFLICT_DETECTED');
      }
      const entry = await store.read({ sovereignAssetId: FIXTURE.sovereignAssetId, issuer: FIXTURE.registrant.issuer });
      assert.equal(entry.mark.conflict, true);
      assert.equal(entry.mark.withdrawn, true);
      assert.equal(entry.mark.sequence, 2);
      assert.equal(entry.mark.timeFloor, '2026-10-28T11:55:00Z');
      second.close();
      store.close();
    });
  });

  it('retired terms survive a restart and cannot be revived', async () => {
    await withDatabase(async (path) => {
      const eligibility = await eligible();
      let store = await openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE, create: true });
      await bootstrap(store, S.active1, '2026-10-28T12:00:00Z');
      assert.equal((await check(eligibility, store, S.superseding2, '2026-10-28T12:00:00Z')).freshnessVerdict, 'SUPERSEDED');
      store.close();
      store = await reopen(path);
      const entry = await store.read({ sovereignAssetId: FIXTURE.sovereignAssetId, issuer: FIXTURE.registrant.issuer });
      assert.deepEqual(entry.mark.retiredTermsDigests, [FIXTURE.terms.claimDigest]);
      assert.equal((await check(eligibility, store, S.reviving3, '2026-10-28T12:01:00Z')).freshnessVerdict, 'CONFLICT_DETECTED');
      store.close();
      store = await reopen(path);
      assert.equal((await check(eligibility, store, S.reviving3, '2026-10-28T12:02:00Z')).freshnessVerdict, 'CONFLICT_DETECTED');
      store.close();
    });
  });

  it('two connections racing equivocating sequence-2 statuses: at most one is accepted, and the conflict is durable', async () => {
    await withDatabase(async (path) => {
      const eligibility = await eligible();
      const a = await openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE, create: true });
      await bootstrap(a, S.active1, '2026-10-28T12:00:00Z');
      const b = await reopen(path);
      const results = await Promise.all([check(eligibility, a, S.withdrawn2, '2026-10-28T12:00:00Z'), check(eligibility, b, S.equivocating2, '2026-10-28T12:00:00Z')]);
      assert.equal(results.filter((r) => r.history.transition === 'advanced').length, 1);
      assert.equal(results.filter((r) => r.freshnessVerdict === 'CONFLICT_DETECTED').length, 1);
      assert.ok(results.every((r) => r.policyDecisionAfterFreshness === 'DENIED'), 'withdrawn or conflicted, never allowed');
      a.close();
      b.close();
      const c = await reopen(path);
      assert.equal((await c.read({ sovereignAssetId: FIXTURE.sovereignAssetId, issuer: FIXTURE.registrant.issuer })).mark.conflict, true);
      c.close();
    });
  });

  it('the SQLite store and the in-memory reference give identical gate results for the same sequence of operations', async () => {
    const eligibility = await eligible();
    const script = async (store) => {
      const out = [];
      out.push(await bootstrap(store, S.active1, '2026-10-28T12:00:00Z'));
      out.push(await check(eligibility, store, S.active1, '2026-10-28T12:00:00Z'));
      out.push(await check(eligibility, store, S.withdrawn2, '2026-10-28T12:01:00Z'));
      out.push(await check(eligibility, store, S.withdrawn2, '2026-10-28T12:01:30Z'));
      out.push(await check(eligibility, store, S.active1, '2026-10-28T12:02:00Z'));
      out.push(await check(eligibility, store, S.active1, '2026-10-28T11:54:00Z'));
      out.push(await bootstrap(store, S.reopening3, '2026-10-28T12:03:00Z', { reanchor: true }));
      out.push(await check(eligibility, store, S.equivocating2, '2026-10-28T12:03:00Z'));
      out.push(await check(eligibility, store, S.withdrawn2, '2026-10-28T12:04:00Z'));
      out.push(await bootstrap(store, S.withdrawn2, '2026-10-28T12:05:00Z', { reanchor: true }));
      return out;
    };
    const memory = await script(createInMemoryStatusHighWaterMarkStore());
    const durable = await withDatabase(async (path) => {
      const store = await openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE, create: true });
      try {
        return await script(store);
      } finally {
        store.close();
      }
    });
    assert.deepEqual(durable, memory);
    assert.deepEqual(memory.map((r) => (typeof r === 'string' ? r : r.freshnessVerdict)), [
      'ESTABLISHED', 'FRESH', 'WITHDRAWN', 'WITHDRAWN', 'ROLLBACK_DETECTED', 'CLOCK_ROLLBACK_DETECTED',
      'REANCHOR_REACTIVATES_WITHDRAWN', 'CONFLICT_DETECTED', 'CONFLICT_DETECTED', 'CONFLICT_DETECTED',
    ]);
  });

  it('a corrupt durable row fails closed through the real gate, never as an empty history', async () => {
    await withDatabase(async (path) => {
      const eligibility = await eligible();
      const store = await openSqliteStatusHighWaterMarkStore(path, { namespace: NAMESPACE, create: true });
      await bootstrap(store, S.active1, '2026-10-28T12:00:00Z');
      const { default: Database } = await import('better-sqlite3');
      const db = new Database(path);
      db.pragma('ignore_check_constraints = ON');
      db.exec('DROP TRIGGER sovereign_status_history_forward_only');
      db.exec("UPDATE sovereign_status_history SET status_digest = 'tampered'");
      db.close();
      const result = await check(eligibility, store, S.active1, '2026-10-28T12:00:00Z');
      assert.equal(result.freshnessVerdict, 'HISTORY_STORE_UNAVAILABLE');
      assert.equal(result.policyDecisionAfterFreshness, 'DENIED');
      store.close();
    });
  });
});

/**
 * Contract drift, checked statically without importing the portable package into the Host layer: the
 * declarations the receiver package publishes and the ones the Host adapter mirrors must name the same
 * fields with the same types, readonly-ness and optionality.
 */
describe('FV-P4C-2A — the adapter mirrors the published store contract exactly', () => {
  const declarations = (file) => readFileSync(file, 'utf8');
  const fields = (text, name) => {
    const match = new RegExp(`export interface ${name} \\{([^}]*)\\}`).exec(text);
    assert.ok(match, `interface ${name} is declared`);
    return Object.fromEntries(
      match[1]
        .replace(/\/\*\*[\s\S]*?\*\//g, '')
        .split(';')
        .map((line) => line.trim())
        .filter(Boolean)
        .map((line) => {
          const parsed = /^(readonly )?(\w+)(\??): (.+)$/s.exec(line.replace(/\s+/g, ' '));
          assert.ok(parsed, `parsable member: ${line}`);
          return [parsed[2], `${parsed[1] ?? ''}${parsed[3]}${parsed[4]}`];
        }),
    );
  };
  const packageTypes = declarations(join(require.resolve('@aoc-enterprise/sovereign-receiver-verification'), '..', 'document-freshness-types.d.ts'));
  const adapterTypes = declarations(new URL('../dist/src/enterprise/sovereign-status-history/sqlite-status-high-water-mark-store.d.ts', import.meta.url));
  for (const [published, mirrored] of [
    ['StatusHighWaterMark', 'SovereignStatusHighWaterMark'],
    ['StatusHighWaterMarkEntry', 'SovereignStatusHighWaterMarkEntry'],
    ['StatusHistoryKey', 'SovereignStatusHistoryKey'],
  ]) {
    it(`${mirrored} matches ${published}`, () => {
      const expected = fields(packageTypes, published);
      const actual = fields(adapterTypes, mirrored);
      // The entry's mark is the mirrored mark type; everything else is compared verbatim.
      if (published === 'StatusHighWaterMarkEntry') expected.mark = expected.mark.replace('StatusHighWaterMark', 'SovereignStatusHighWaterMark');
      assert.deepEqual(actual, expected);
      assert.ok(Object.keys(expected).length > 0);
    });
  }
  it('the adapter offers exactly the two contract methods with the published parameter and result shapes', () => {
    const store = /export interface StatusHighWaterMarkStore \{([^}]*)\}/.exec(packageTypes)[1].replace(/\/\*\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').trim();
    const mirrored = /export interface SqliteStatusHighWaterMarkStore \{([^}]*)\}/.exec(adapterTypes)[1].replace(/\/\*\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').trim();
    const normalize = (text) => text.replace(/SovereignStatusHighWaterMarkEntry/g, 'StatusHighWaterMarkEntry').replace(/SovereignStatusHighWaterMark/g, 'StatusHighWaterMark').replace(/SovereignStatusHistoryKey/g, 'StatusHistoryKey');
    for (const method of store.split(';').map((m) => m.trim()).filter(Boolean)) assert.ok(normalize(mirrored).includes(method), `mirrors: ${method}`);
  });
});
